// 原Family历史读与本域精确边界交叉；占领夹具只测试漏登记拒绝，不冒军事占领运行。
#define main political_succession_office_only
#include "political_succession_sources_test.cpp"
#undef main
#include "resident/domains/politics/successor_rounds/political_successor_round_control.hpp"
#include "resident/domains/family/family_model.hpp"
#include "resident/domains/politics/takeover/politics_takeover_state.hpp"
#include "resident/domains/military/military_model.hpp"
// 新边界由Common实际分配；旧死亡继位头不能借入本业务。
StableId boundary_source(Fixture& f){auto id=take(f.common.next_id("political_successor_round_nomination"));take(f.common.append_fact({id,"political_successor_round_nominated",political_successor_rounds_domain}));return id;}
int main(){try{
 Fixture f;FamilyState family;family.founder_actor_id="leader";f.common.state().metadata.player_actor_id="leader";auto boundary=boundary_source(f);check(take(read_political_successor_round_player_before_fact(f.common,family,nullptr,0,boundary))=="leader","original Family founder owns exact first business boundary");
 auto changed=take(f.common.next_id("family"));take(f.common.append_fact({changed,"family_succession","family"}));FamilyChoice choice;choice.kind="family_succession";choice.guardian_actor_id="leader";choice.heir_actor_id="candidate";choice.tick=0;family.facts.insert(changed,choice);family.successions.push_back(changed);f.common.state().metadata.player_actor_id="candidate";check(take(read_political_successor_round_player_before_fact(f.common,family,nullptr,0,boundary))=="leader","later same-tick original control preserves former player's signature");auto later=boundary_source(f);check(take(read_political_successor_round_player_before_fact(f.common,family,nullptr,0,later))=="candidate","real earlier control is available only to later source");
 auto headers=f.common.state().facts;f.common.state().facts={};f.common.state().facts.insert(changed,*headers.find(changed));f.common.state().facts.insert(boundary,*headers.find(boundary));f.common.state().facts.insert(later,*headers.find(later));check(!read_political_successor_round_player_before_fact(f.common,family,nullptr,0,boundary).ok,"moving original control head across allocation cutoff cannot forge old player");f.common.state().facts=headers;check(!read_political_successor_round_player_before_fact(f.common,family,nullptr,0,changed).ok,"arbitrary actual Family head cannot become succession signature boundary");check(!read_political_successor_round_player_before_fact(f.common,family,nullptr,1,later).ok,"future player boundary rejected");
 PoliticsCatalog catalog;catalog.enabled=true;Jurisdiction j;j.id="capital";j.seat_place_id="hall";j.office_id="chief";j.political_organization_id=j.controlling_organization_id="city";catalog.jurisdictions.insert(j.id,j);PoliticsState politics;politics.jurisdictions=catalog.jurisdictions;PoliticalSuccessionTerritoryContext territory{f.common,politics,catalog};check(validate_political_successor_round_seat(territory,f.policy,0).ok,"explicit original jurisdiction and head seat permit current read");check(validate_political_successor_round_seat(territory,f.policy,0,boundary).ok,"exact historical signature uses original seat source");auto wrong=f.policy;wrong.jurisdiction_id="elsewhere";check(!validate_political_successor_round_seat(territory,wrong,0).ok,"no inferred world-wide jurisdiction");politics.jurisdictions.find("capital")->revision=1;check(!validate_political_successor_round_seat(territory,f.policy,0).ok,"current revision cannot claim no history");politics.jurisdictions=catalog.jurisdictions;catalog.jurisdictions.find("capital")->office_id="other";check(!validate_political_successor_round_seat(territory,f.policy,0).ok,"same-place different office cannot borrow head policy");catalog.jurisdictions.find("capital")->office_id="chief";
 PoliticalTakeoverCatalog takeover_catalog;takeover_catalog.enabled=true;PoliticalTakeoverRule rule;rule.id="capture";rule.jurisdiction_id="capital";rule.garrison_id="garrison";rule.stronghold_id="fort";takeover_catalog.rules.insert(rule.id,rule);PoliticalTakeoverState takeovers;MilitaryState military;MilitaryCatalog military_catalog;MilitaryAccess military_access;PoliticalSuccessionOccupationContext occupation{takeovers,takeover_catalog,military,military_catalog,military_access};territory.occupations=&occupation;MilitaryOccupationFact captured;captured.id="military:999";captured.garrison_id="garrison";captured.stronghold_id="fort";captured.assets_applied=true;military.occupation_facts.push_back(captured);check(!validate_political_successor_round_seat(territory,f.policy,0).ok,"actual selected asset application cannot omit its political registration");
 std::cout<<checks<<" checks; typed boundaries only, no World run claimed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
